   for(let q=y0+1;q<=R;q++){if(!isP(q))continue;for(let c=q;q*c<=N;c++){if(!isP(c))continue;const m=q*c;nc++;const U=2*q+c,t=8*m;const k=U-rt(t)<=2?2:1;if(k===2)n2++;out.parity[m]=k;let r=Math.floor((Math.sqrt(8*m+1)-1)/2);if(r*(r+1)/2>=m)r--;X[m]=m-r*(r+1)/2-(r+1)/2;Y[m]=r;}}
